CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 NUMBER, arg4 NUMBER)
AS
  v_total NUMBER := 0;
  v_orig_price NUMBER;
  v_new_no NUMBER;
  v_new_price NUMBER;
  v_prefix VARCHAR2(30) := 'prefix_';
BEGIN
  FOR rec IN (
    SELECT "No", "Grape", "Winery", "Price", "Score", "Cases"
    FROM "wine"
    WHERE "Score" >= arg1
    ORDER BY "No"
  ) LOOP
    v_total := v_total + rec."Price";
    IF instr(rec."Grape", v_prefix) = 1 THEN
      UPDATE "wine"
      SET "Price" = arg3
      WHERE "No" = rec."No";
    ELSIF rec."No" < arg4 THEN
      DELETE FROM "wine"
      WHERE "No" = rec."No";
    ELSIF rec."Winery" = 'Twomey' THEN
      UPDATE "wine"
      SET "Price" = rec."Price" + arg3
      WHERE "No" = rec."No";
    ELSIF rec."Cases" > rec."Score" THEN
      UPDATE "wine"
      SET "Price" = arg3 + rec."Price"
      WHERE "No" = rec."No";
    ELSE
      UPDATE "wine"
      SET "Price" = 3 * arg3
      WHERE "No" = rec."No";
    END IF;
  END LOOP;

  BEGIN
    SELECT MAX("No") INTO v_new_no FROM "wine";
  EXCEPTION
    WHEN NO_DATA_FOUND THEN v_new_no := NULL;
  END;

  IF v_new_no IS NULL THEN
    v_new_no := 1;
  ELSE
    v_new_no := v_new_no + 1;
  END IF;

  IF v_total > arg4 THEN
    v_new_price := arg3 + 1;
  ELSE
    v_new_price := arg3;
  END IF;

  INSERT INTO "wine" ("No", "Score", "Grape", "Price")
  VALUES (v_new_no, arg1 + 1, v_prefix || arg2, v_new_price);
END;

